7	#[derive(Default)]
8	pub(super) struct MemberChainGroupsBuilder {
9	    /// keeps track of the groups created
10	    groups: Vec<MemberChainGroup>,
11	    /// keeps track of the current group that is being created/updated
12	    current_group: Option<MemberChainGroup>,
13	}
