15	impl MemberChainGroupsBuilder {
16	    /// starts a new group
17	    pub fn start_group(&mut self, member: ChainMember) {
18	        debug_assert!(self.current_group.is_none());
19	        let mut group = MemberChainGroup::default();
20	        group.members.push(member);
21	        self.current_group = Some(group);
22	    }
23	
24	    /// continues of starts a new group
25	    pub fn start_or_continue_group(&mut self, member: ChainMember) {
26	        match &mut self.current_group {
27	            None => self.start_group(member),
28	            Some(group) => group.members.push(member),
29	        }
30	    }
31	
32	    /// adds the passed element to the current group.
33	    ///
34	    /// # Panics
35	    ///
36	    /// If there's no started group.
37	    pub fn continue_group(&mut self, member: ChainMember) {
38	        match &mut self.current_group {
39	            None => {
40	                panic!("It is necessary to start a group first using `start_group`.");
41	            }
42	            Some(group) => {
43	                group.members.push(member);
44	            }
45	        }
46	    }
47	
48	    /// clears the current group, and adds it to the groups collection
49	    pub fn close_group(&mut self) {
50	        if let Some(group) = self.current_group.take() {
51	            self.groups.push(group);
52	        }
53	    }
54	
55	    pub(super) fn finish(self) -> TailChainGroups {
56	        let mut groups = self.groups;
57	
58	        if let Some(group) = self.current_group {
59	            groups.push(group);
60	        }
61	
62	        TailChainGroups { groups }
63	    }
64	}
