66	/// Groups following on the head group.
67	///
68	/// May be empty if all members are part of the head group
69	#[derive(Clone, Debug)]
70	pub(super) struct TailChainGroups {
71	    groups: Vec<MemberChainGroup>,
72	}
73	
74	impl TailChainGroups {
75	    /// Returns `true` if there are no tail groups.
76	    pub(crate) fn is_empty(&self) -> bool {
77	        self.groups.is_empty()
78	    }
79	
80	    /// Returns the number of tail groups.
81	    pub(crate) fn len(&self) -> usize {
82	        self.groups.len()
83	    }
84	
85	    /// Returns the first group
86	    pub(crate) fn first(&self) -> Option<&MemberChainGroup> {
87	        self.groups.first()
88	    }
89	
90	    /// Returns the last group
91	    pub(crate) fn last(&self) -> Option<&MemberChainGroup> {
92	        self.groups.last()
93	    }
94	
95	    /// Removes the first group and returns it
96	    pub(super) fn pop_first(&mut self) -> Option<MemberChainGroup> {
97	        match self.groups.len() {
98	            0 => None,
99	            _ => Some(self.groups.remove(0)),
100	        }
101	    }
102	
103	    /// Checks if the groups contain comments.
104	    pub fn has_comments(&self, comments: &JsComments) -> bool {
105	        let mut members = self.groups.iter().flat_map(|item| item.members.iter());
106	
107	        let has_comments = members.any(|item| {
108	            comments.has_trailing_comments(item.syntax())
109	                || comments.has_leading_comments(item.syntax())
110	        });
111	
112	        let cutoff_has_leading_comments = if !self.groups.is_empty() {
113	            let group = self.groups.get(1);
114	            if let Some(group) = group {
115	                let first_item = group.members.first();
116	                first_item.map_or(false, |first_item| {
117	                    comments.has_leading_comments(first_item.syntax())
118	                })
119	            } else {
120	                false
121	            }
122	        } else {
123	            false
124	        };
125	
126	        has_comments || cutoff_has_leading_comments
127	    }
128	
129	    /// Here we check if the length of the groups exceeds the cutoff or there are comments
130	    /// This function is the inverse of the prettier function
131	    /// [Prettier applies]: https://github.com/prettier/prettier/blob/a043ac0d733c4d53f980aa73807a63fc914f23bd/src/language-js/print/member-chain.js#L342
132	    pub(crate) fn is_member_call_chain(&self, comments: &JsComments) -> bool {
133	        self.groups.len() > 1 || self.has_comments(comments)
134	    }
135	
136	    /// Returns an iterator over the groups.
137	    pub(super) fn iter(&self) -> impl Iterator<Item = &MemberChainGroup> + DoubleEndedIterator {
138	        self.groups.iter()
139	    }
140	
141	    /// Test if any group except the last group [break](FormatElements::will_break).
142	    pub(super) fn any_except_last_will_break(&self, f: &mut JsFormatter) -> FormatResult<bool> {
143	        for group in &self.groups[..self.groups.len().saturating_sub(1)] {
144	            if group.will_break(f)? {
145	                return Ok(true);
146	            }
147	        }
148	
149	        Ok(false)
150	    }
151	
152	    /// Returns an iterator over all members
153	    pub(super) fn members(&self) -> impl Iterator<Item = &ChainMember> + DoubleEndedIterator {
154	        self.groups.iter().flat_map(|group| group.members().iter())
155	    }
156	}
