158	impl Format<JsFormatContext> for TailChainGroups {
159	    fn fmt(&self, f: &mut Formatter<JsFormatContext>) -> FormatResult<()> {
160	        f.join().entries(self.groups.iter()).finish()
161	    }
162	}
