164	#[derive(Clone, Default)]
165	pub(super) struct MemberChainGroup {
166	    members: Vec<ChainMember>,
167	
168	    /// Stores the formatted result of this group.
169	    ///
170	    /// Manual implementation of `Memoized` to only memorizing the formatted result
171	    /// if [MemberChainGroup::will_break] is called but not otherwise.
172	    formatted: RefCell<Option<FormatElement>>,
173	}
174	
175	impl MemberChainGroup {
176	    pub(super) fn into_members(self) -> Vec<ChainMember> {
177	        self.members
178	    }
179	
180	    /// Returns the chain members of the group.
181	    pub(super) fn members(&self) -> &[ChainMember] {
182	        &self.members
183	    }
184	
185	    /// Extends the members of this group with the passed in members
186	    pub(super) fn extend_members(&mut self, members: impl IntoIterator<Item = ChainMember>) {
187	        self.members.extend(members)
188	    }
189	
190	    /// Tests if the formatted result of this group results in a [break](FormatElements::will_break).
191	    pub(super) fn will_break(&self, f: &mut JsFormatter) -> FormatResult<bool> {
192	        let mut cell = self.formatted.borrow_mut();
193	        let result = match cell.as_ref() {
194	            Some(formatted) => formatted.will_break(),
195	            None => {
196	                let interned = f.intern(&FormatMemberChainGroup { group: self })?;
197	
198	                if let Some(interned) = interned {
199	                    let breaks = interned.will_break();
200	                    *cell = Some(interned);
201	                    breaks
202	                } else {
203	                    false
204	                }
205	            }
206	        };
207	
208	        Ok(result)
209	    }
210	
211	    pub(super) fn has_comments(&self, comments: &JsComments) -> bool {
212	        self.members.iter().enumerate().any(|(index, member)| {
213	            if index == 0 {
214	                comments.has_trailing_comments(member.syntax())
215	            } else if index < self.members.len() {
216	                comments.has_leading_comments(member.syntax())
217	                    || comments.has_trailing_comments(member.syntax())
218	            } else {
219	                false
220	            }
221	        })
222	    }
